from falcor import *

def render_graph_DefaultRenderGraph():
    g = RenderGraph('DefaultRenderGraph')
    loadRenderPassLibrary('AccumulatePass.dll')
    loadRenderPassLibrary('FLIPPass.dll')
    loadRenderPassLibrary('BlitPass.dll')
    loadRenderPassLibrary('PathTracer.dll')
    loadRenderPassLibrary('DepthPass.dll')
    loadRenderPassLibrary('GBuffer.dll')
    loadRenderPassLibrary('GlobalIlluminationPass.dll')
    loadRenderPassLibrary('WhittedRayTracer.dll')
    loadRenderPassLibrary('ImageLoader.dll')
    loadRenderPassLibrary('ModulateIllumination.dll')
    loadRenderPassLibrary('NRDPass.dll')
    loadRenderPassLibrary('PixelInspectorPass.dll')
    loadRenderPassLibrary('SkyBox.dll')
    loadRenderPassLibrary('RTXDIPass.dll')
    loadRenderPassLibrary('RTXGIPass.dll')
    loadRenderPassLibrary('SSGAFModulateIllumination.dll')
    loadRenderPassLibrary('SSGAFPass.dll')
    loadRenderPassLibrary('SVGFAdaptiveSampling.dll')
    loadRenderPassLibrary('SVGFIndividualPass.dll')
