    g.addEdge('PathTracer.nrdDeltaReflectionRadianceHitDist', 'SSGAFModulateIllumination.deltaReflectionRadiance')
    g.addEdge('PathTracer.nrdDeltaTransmissionReflectance', 'SSGAFModulateIllumination.deltaTransmissionReflectance')
    g.addEdge('PathTracer.nrdDeltaTransmissionRadianceHitDist', 'SSGAFModulateIllumination.deltaTransmissionRadiance')
    g.addEdge('PathTracer.nrdDeltaTransmissionEmission', 'SSGAFModulateIllumination.deltaTransmissionEmission')
    g.addEdge('PathTracer.nrdDeltaReflectionEmission', 'SSGAFModulateIllumination.deltaReflectionEmission')
